Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
In gb_lights_light_config(), `light->channels_count` was assigned before allocating the `light->channels` array. If the memory allocation via `kcalloc()` fails, the cleanup path (e.g., `gb_lights_release()`) iterates based on the non-zero `channels_count` and attempts to dereference the still-NULL `channels` pointer, causing a NULL pointer dereference.

Here is the patch:

 static int gb_lights_light_config(struct gb_lights *glights, u8 id)
 {
 	struct gb_light *light = &glights->lights[id];
 	struct gb_lights_get_light_config_request req;
 	struct gb_lights_get_light_config_response conf;
 	int ret;
 	int i;

 	light->glights = glights;
 	light->id = id;

 	req.id = id;

 	ret = gb_operation_sync(glights->connection,
 				GB_LIGHTS_TYPE_GET_LIGHT_CONFIG,
 				&req, sizeof(req), &conf, sizeof(conf));
 	if (ret < 0)
 		return ret;

 	if (!conf.channel_count)
 		return -EINVAL;
 	if (!strlen(conf.name))
 		return -EINVAL;

-	light->channels_count = conf.channel_count;
 	light->name = kstrndup(conf.name, NAMES_MAX, GFP_KERNEL);
 	if (!light->name)
 		return -ENOMEM;
-	light->channels = kcalloc(light->channels_count,
+	light->channels = kcalloc(conf.channel_count,
 				  sizeof(struct gb_channel), GFP_KERNEL);
 	if (!light->channels)
 		return -ENOMEM;
+	/*
+	 * Publish channels_count only after channels allocation so cleanup
+	 * doesn't walk a NULL channels pointer on allocation failure.
+	 */
+	light->channels_count = conf.channel_count;

 	/* First we collect all the configurations for all channels */
 	for (i = 0; i < light->channels_count; i++) {
 		light->channels[i].id = i;
 		ret = gb_lights_channel_config(light, &light->channels[i]);
 		if (ret < 0)
 			return ret;
 	}

 	return 0;
 }



